insert into public.product_variants (product_slug,selections,image_path,sort_order,is_active) select 'korfad-ex-animas',jsonb_build_object('color',color,'configuration',configuration),image_path,sort_order,true from korfad_ex_animas on conflict (product_slug,selections) do update set image_path=excluded.image_path,sort_order=excluded.sort_order,is_active=true;
insert into public.product_sources (product_slug,source_name,source_url,source_product_name,verification_status,verified_at,notes) select 'korfad-ex-animas','KORFAD — офіційний каталог',source_url,'ANIMAS','verified',now(),'Імпортовано з офіційних карток KORFAD: точні фото кольорів і виконань OUTSIDE / INSIDE.' from korfad_ex_animas where not exists (select 1 from public.product_sources where product_slug='korfad-ex-animas' and source_url=korfad_ex_animas.source_url);
insert into public.product_media (product_slug,kind,label,image_path,sort_order) select 'korfad-ex-animas','main','Головне фото',min(image_path),0 from korfad_ex_animas where not exists (select 1 from public.product_media where product_slug='korfad-ex-animas' and kind='main');
insert into public.product_media (product_slug,kind,label,image_path,sort_order) select 'korfad-ex-animas','gallery','Колір: '||color||' · '||configuration,image_path,sort_order from korfad_ex_animas source where not exists (select 1 from public.product_media media where media.product_slug='korfad-ex-animas' and media.kind='gallery' and media.image_path=source.image_path);
