-- KORFAD · EXELLENCE · ANIMAS. 5 декорів × OUTSIDE / INSIDE.
begin;
create temporary table korfad_ex_animas (color text, configuration text, image_path text, source_url text, sort_order integer) on commit drop;
select 'korfad-ex-animas','interior','KORFAD','EXELLENCE','KORFAD ANIMAS','Фарбоване покриття','Сучасний','Заводські кольори RAL','Ціна за запитом','KORFAD ANIMAS — фарбовані міжкімнатні двері колекції EXELLENCE. Доступні підтверджені кольори RAL і виконання OUTSIDE або INSIDE; точну комплектацію й ціну уточнюйте у менеджера.',jsonb_build_array('Фабрика KORFAD','Колекція EXELLENCE'),min(image_path),99999,false from korfad_ex_animas
on conflict (slug) do update set name=excluded.name,material=excluded.material,style=excluded.style,color=excluded.color,description=excluded.description,image_path=excluded.image_path;
on conflict (product_slug,label) do update set value=excluded.value,sort_order=excluded.sort_order,is_active=true;
select 'korfad-ex-animas','color','Колір',color,null,null,min(sort_order) from korfad_ex_animas group by color
on conflict (product_slug,option_group,label) do update set group_label=excluded.group_label,sort_order=excluded.sort_order,is_active=true;
on conflict (product_slug,option_group,label) do update set group_label=excluded.group_label,sort_order=excluded.sort_order,is_active=true;
commit;
select count(*) as моделей,count(*) filter (where is_available) as опубліковано,(select count(*) from public.product_variants where product_slug='korfad-ex-animas' and is_active) as фото_варіантів from public.products where slug='korfad-ex-animas';
